package org.usbworkbench;
import java.io.*;import java.nio.file.*;import java.util.*;import android.content.*;import android.content.pm.*;
public final class FsImageTest {
 static int checks;static void yes(boolean b,String m){if(!b)throw new AssertionError(m);checks++;}
 static void command(String...args)throws Exception{Process p=new ProcessBuilder(args).redirectErrorStream(true).start();ByteArrayOutputStream log=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=p.getInputStream().read(b))!=-1)log.write(b,0,n);if(p.waitFor()!=0)throw new AssertionError(Arrays.toString(args)+"\n"+log.toString("UTF-8"));}
 public static void main(String[] args)throws Exception{
 File root=new File("artifacts/fsimage-fixtures");root.mkdirs();File libs=new File("app/src/main/jniLibs/arm64-v8a").getAbsoluteFile();Context c=new Context(){final ApplicationInfo i=new ApplicationInfo();{i.nativeLibraryDir=libs.getPath();}public ApplicationInfo getApplicationInfo(){return i;}public File getFilesDir(){return root;}};File payload=new File(root,"payload.txt");byte[] data="Owned NTFS/ext image fixture / ورشة".getBytes("UTF-8");Files.write(payload.toPath(),data);
 for(String kind:new String[]{"ntfs","ext2","ext3","ext4"}){File image=new File(root,kind+".img");image.delete();try{try(NativeIntegrationTest.Image disk=new NativeIntegrationTest.Image(image,64L*1048576)){NativeTools.format(c,disk,kind,"OWNED",0,(a,b)->{},()->false);}
 if(kind.equals("ntfs")){command(new File(libs,"libntfscp.so").getPath(),"-f",image.getAbsolutePath(),payload.getAbsolutePath(),"/hello.txt");command(new File(libs,"libntfscp.so").getPath(),"-f",image.getAbsolutePath(),payload.getAbsolutePath(),"/ورشة.txt");}
 else{command("/data/data/com.termux/files/usr/glibc/bin/debugfs","-w","-R","write "+payload.getAbsolutePath()+" /hello.txt",image.getAbsolutePath());command("/data/data/com.termux/files/usr/glibc/bin/debugfs","-w","-R","write "+payload.getAbsolutePath()+" /ورشة.txt",image.getAbsolutePath());command("/data/data/com.termux/files/usr/glibc/bin/debugfs","-w","-R","symlink /shortcut hello.txt",image.getAbsolutePath());}
 try(OpticalImage.Source original=ArchiveTest.source(image)){String before=ArchiveTools.hash(original,(a,b)->{},()->false);FsImageTools.View view=FsImageTools.open(original,0);yes(view.kind.equals(kind.equals("ntfs")?"ntfs":"ext"),"detected kind");if(kind.equals("ntfs")){UsbAnalyzer.Space stats=ArchiveTools.statistics(libs,view.source,(a,b)->{},()->false);yes(stats.total>0&&stats.total<=original.size()&&stats.free>0&&stats.free<stats.total,"native NTFS bitmap stats bounds");yes(stats.label.equals("OWNED"),"native volume label");}
ArchiveTools.Manifest plan=ArchiveTools.scanFilesystem(libs,view.source,1048576,(a,b)->{},()->false,view.kind);yes(plan.entries.stream().anyMatch(e->e.path.equals("hello.txt")),"file listed "+kind);yes(plan.entries.stream().anyMatch(e->e.path.equals("ورشة.txt")),"Unicode listed");if(!kind.equals("ntfs"))yes(plan.entries.stream().anyMatch(e->e.path.equals("shortcut")&&e.special),"symlink marked without following");Map<String,ArchiveTools.MemoryFile> saved=new HashMap<>();Map<String,String> hashes=ArchiveTools.extract(libs,view.source,plan,new WimFiles.Store(){public void capacity(long n){}public WimFiles.RandomFile create(String name){ArchiveTools.MemoryFile f=new ArchiveTools.MemoryFile();saved.put(name,f);return f;}},(a,b)->{},()->false);for(ArchiveTools.Entry e:plan.entries)if(!e.directory&&!e.special){yes(Arrays.equals(data,saved.get(e.output()).data()),"independent source bytes "+e.path);yes(hashes.containsKey(e.output()),"writehash");}yes(before.equals(ArchiveTools.hash(original,(a,b)->{},()->false)),"source image unchanged after private library close");}
 try(NativeIntegrationTest.Image disk=new NativeIntegrationTest.Image(image,64L*1048576)){long[] read={0};BlockDevice audited=new BlockDevice(){public int blockSize(){return 512;}public long blockCount(){return disk.blockCount();}public void read(long at,byte[] b,int n)throws IOException{read[0]+=n;disk.read(at,b,n);}public void write(long at,byte[] b,int n)throws IOException{throw new IOException("READ_ONLY");}public void sync(){}public void close(){}};String report=new UsbAnalyzer(audited,(a,b)->{},part->{UsbFileSource source=new UsbFileSource(part);return ArchiveTools.statistics(libs,source,(a,b)->{},()->false);}).analyze();String rendered=UsbAnalyzer.render(report,false);yes(rendered.contains("Free space:")&&!rendered.contains("analysis incomplete"),"actual analyzer "+kind);yes(rendered.contains(kind.equals("ntfs")?"NTFS allocation bitmap":"Superblock counters"),"documented space source");yes(disk.writes==0,"native analyzer source never written");read[0]=0;UsbFileSource live=new UsbFileSource(audited);FsImageTools.View v=FsImageTools.open(live,0);ArchiveTools.Manifest m=ArchiveTools.scanFilesystem(libs,v.source,1048576,(a,b)->{},()->false,v.kind,false);yes(m.sourceHash.isEmpty()&&read[0]<16L*1048576,"metadata-only live listing, no whole drive cache/hash");Map<String,ArchiveTools.MemoryFile> contents=new HashMap<>();live.invalidate();ArchiveTools.extract(libs,v.source,m,new WimFiles.Store(){public void capacity(long n){}public WimFiles.RandomFile create(String name){ArchiveTools.MemoryFile f=new ArchiveTools.MemoryFile();contents.put(name,f);return f;}},(a,b)->{},()->false);for(ArchiveTools.Entry e:m.entries)if(!e.directory&&!e.special)yes(Arrays.equals(data,contents.get(e.output()).data()),"unaligned cached block IO content");yes(disk.writes==0,"live backend never writes source");}
 System.out.println("PASS actual read-only filesystem image list/extract/Unicode "+kind);
 }finally{image.delete();}}
 System.out.println("PASS: "+checks+" NTFS/ext2/3/4 native readonly list/extraction/hash/Arabic/source-preservation assertions");
 }
}
